@once
@push('styles')
<style>
.branch-social{margin:22px 0}.branch-social .branch-social__title{margin:0 0 12px;font-size:15px;font-weight:600;line-height:1.4;color:#20262b}.branch-social__links{display:flex;flex-wrap:wrap;gap:10px}.branch-social a.branch-social__link{display:inline-flex;align-items:center;gap:10px;min-height:64px;padding:10px 14px;border:1px solid #e1e4e7;border-radius:12px;background:#fff;color:#20262b;text-decoration:none;line-height:1.3;transition:border-color .2s,box-shadow .2s}.branch-social__link>span:last-child{min-width:0}.branch-social__link strong{display:block;font-size:14px;font-weight:600}.branch-social__link small{display:block;margin-top:3px;font-size:12px;color:#687078;overflow-wrap:anywhere}.branch-social__icon{display:flex;align-items:center;justify-content:center;width:36px;height:36px;flex:0 0 36px;border-radius:10px}.branch-social__icon svg{display:block;width:22px;height:22px}.is-telegram .branch-social__icon{background:#e9f5fc;color:#229ed9}.is-viber .branch-social__icon{background:#f1ecfa;color:#7360a8}.is-instagram .branch-social__icon{background:#fcecf3;color:#c13584}.branch-social a.branch-social__link:hover{border-color:#aab2b9;box-shadow:0 3px 12px #18232c0d}.branch-social a.branch-social__link:focus-visible{outline:2px solid #20262b;outline-offset:3px}@media(max-width:575px){.branch-social__links{display:grid;grid-template-columns:1fr}.branch-social a.branch-social__link{width:100%}}
</style>
<style>
.is-whatsapp .branch-social__icon{background:#e9f8ef;color:#128c4a}.wtb .is-whatsapp .branch-social__icon svg{stroke:currentColor}
</style>
<style>
.wtb__social .branch-social{margin:6px 0 0}.wtb__social .branch-social__title,.wtb__social .branch-social__link small{display:none}.wtb__social .branch-social__links{display:flex;flex-wrap:wrap;gap:6px}.wtb__social a.branch-social__link{min-height:36px;padding:4px 8px;gap:6px;border-radius:8px}.wtb__social .branch-social__icon{width:24px;height:24px;flex-basis:24px;border-radius:6px}.wtb__social .branch-social__icon svg{width:17px;height:17px}.wtb__social .branch-social__link strong{font-size:11px}.wtb__social a.branch-social__link{width:auto}.wtb .branch-social__icon svg{stroke:none}.wtb .is-viber .branch-social__icon svg,.wtb .is-instagram .branch-social__icon svg{stroke:currentColor}
</style>
@endpush
@endonce
